-- Scaffold generated by SMELTER from frozen contract predator-controller-v1.
-- The constructor validation and method shapes match the contract interface.
-- Fill in ONE helper at a time (search for TODO), then run the tests.
-- Pure module: no os, io, require, print, _G or module-level mutable state.
local M = {}

function M.new(deps)
  if type(deps) ~= "table" then
    return nil, "deps_not_table"
  end
  if type(deps.adapter) ~= "table" then
    return nil, "adapter_must_be_table"
  end
  if type(deps.adapter.position) ~= "function" then
    return nil, "unsupported_capability:position"
  end
  if type(deps.adapter.describe) ~= "function" then
    return nil, "unsupported_capability:describe"
  end
  if type(deps.adapter.candidates) ~= "function" then
    return nil, "unsupported_capability:candidates"
  end
  if type(deps.adapter.move_to) ~= "function" then
    return nil, "unsupported_capability:move_to"
  end
  if type(deps.adapter.attack) ~= "function" then
    return nil, "unsupported_capability:attack"
  end
  if type(deps.adapter.stop) ~= "function" then
    return nil, "unsupported_capability:stop"
  end
  if type(deps.evaluate) ~= "function" then
    return nil, "evaluate_must_be_function"
  end
  if type(deps.policy) ~= "table" then
    return nil, "policy_must_be_table"
  end
  if type(deps.clock) ~= "function" then
    return nil, "clock_must_be_function"
  end
  if type(deps.profile) ~= "table" then
    return nil, "profile_must_be_table"
  end
  do
    local value = deps.profile.detect_radius
    if type(value) ~= "number" or value ~= value or value < 0 then
      return nil, "profile_invalid:detect_radius"
    end
  end
  do
    local value = deps.profile.attack_radius
    if type(value) ~= "number" or value ~= value or value < 0 then
      return nil, "profile_invalid:attack_radius"
    end
  end
  do
    local value = deps.profile.lose_radius
    if type(value) ~= "number" or value ~= value or value < 0 then
      return nil, "profile_invalid:lose_radius"
    end
  end
  do
    local value = deps.profile.attack_cooldown
    if type(value) ~= "number" or value ~= value or value < 0 then
      return nil, "profile_invalid:attack_cooldown"
    end
  end
  if not (deps.profile.attack_radius <= deps.profile.detect_radius) then
    return nil, "profile_rule:attack_radius_le_detect_radius"
  end
  if not (deps.profile.detect_radius <= deps.profile.lose_radius) then
    return nil, "profile_rule:detect_radius_le_lose_radius"
  end

  -- Per-instance state lives here, never at module level.
  local state = {}
  local controller = {}

  -- call: pcall an adapter function; returns true,value or false,reason. nil/false value is a refusal.
  local function call(fn, ...)
    local ok, value, why = pcall(fn, ...)
    if not ok then
      return false, "adapter_error:" .. tostring(value)
    end
    if not value then
      return false, "adapter_refused:" .. tostring(why)
    end
    return true, value
  end

  -- distance: 3D Euclidean distance between {x,y,z} positions, or nil if either is malformed.
  local function distance(p, q)
    if type(p) ~= "table" or type(q) ~= "table" then
      return nil
    end
    for _, k in ipairs({"x", "y", "z"}) do
      if type(p[k]) ~= "number" or type(q[k]) ~= "number" then
        return nil
      end
    end
    local dx, dy, dz = p.x - q.x, p.y - q.y, p.z - q.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
  end

  -- eligible: Return distance when entity is a table, ent.id ~= actor_id, evaluate(ent,pol)==true and dist(origin,pos)<=radius; else nil.
  local function eligible(entity, actor_id, origin, radius)
    if not (type(entity) == "table" and type(entity.id) == "string" and entity.id ~= actor_id) then return nil end
    local ok_pol, pol_result = pcall(deps.evaluate, entity, deps.policy)
    if not ok_pol or not pol_result then return nil end
    local pos = entity.position
    if not pos or type(pos) ~= "table" then return nil end
    local d = distance(origin, pos)
    if d == nil or (radius >= 0 and d > radius) then return nil end
    return d
  end

  -- select_target: call(deps.adapter.candidates, actor_id, origin, ...) with deps.profile.detect_radius; return
  -- id, distance of the nearest eligible candidate (tie: smaller id) or nil.
  local function select_target(actor_id, origin)
    if type(actor_id) ~= "string" or not origin then return nil, nil end
    local ok_c, raw_cands = call(deps.adapter.candidates, actor_id, origin, deps.profile.detect_radius)
    if not ok_c then return nil, nil, raw_cands end
    local best_id, best_d = nil, math.huge
    for _, ent in ipairs(raw_cands or {}) do
      if type(ent) ~= "table" then goto skip end
      local d = eligible(ent, actor_id, origin, deps.profile.detect_radius)
      if d ~= nil and (d < best_d or (d == best_d and type(ent.id) == "string" and ent.id < (best_id or ent.id))) then
        best_id, best_d = ent.id, d
      end
      ::skip::
    end
    return best_id, best_d
  end

  -- current_distance: call(deps.adapter.describe, target_id); return eligible(record, actor_id, origin,
  -- deps.profile.lose_radius) or nil.
  local function current_distance(actor_id, origin, target_id)
    if not target_id or not origin then return nil end
    local ok_d, record = call(deps.adapter.describe, target_id)
    if not ok_d then return nil end
    return eligible(record, actor_id, origin, deps.profile.lose_radius)
  end

  -- 1. origin = call(deps.adapter.position, actor_id); if it fails return action "error" and issue no commands.
  -- 2. s = state[actor_id] or new table. With s.target: d = current_distance(...); if nil, call stop(actor_id)
  -- once, clear target, return "lost".
  -- 3. Without a target: id, d = select_target(actor_id, origin); none -> return "idle". Set s.target = id,
  -- s.moving = false.
  -- 4. d > attack_radius: if not s.moving, call move_to(actor_id, target) (error on refusal), set s.moving;
  -- return "move".
  -- 5. In range: if s.last_attack and deps.clock() - s.last_attack < attack_cooldown return "wait".
  -- 6. call attack(actor_id, target); refusal -> "error" WITHOUT setting s.last_attack; else set it,
  -- s.moving=false, "attack".
  -- update returns {action=idle|move|attack|wait|lost|error, target_id, reason=nonempty string}
  function controller:update(actor_id)
    local ok_pos, origin = call(deps.adapter.position, actor_id)
    if not ok_pos then return {action="error", target_id=nil, reason="position_error"} end

    local s = state[actor_id]
    if not s then s = {}; state[actor_id] = s end

    -- With existing target: check if still valid (describe fails, evaluate rejects, or beyond lose_radius)
    if s.target then
      local d = current_distance(actor_id, origin, s.target)
      if not d then
        local stopped, why = call(deps.adapter.stop, actor_id)
        if not stopped then return {action="error", target_id=nil, reason=why} end
        s.target=nil; s.moving=false
        return {action="lost", target_id=nil, reason="target_lost"}
      end
      -- Retain the distance for reuse on next pass
      s.last_checked_dist = d
    else
      -- No target: search for one
      local id, d, why = select_target(actor_id, origin)
      if why then return {action="error", target_id=nil, reason=why} end
      if not id then return {action="idle", target_id=nil, reason="no_candidates"} end
      s.target=id; s.target_id=id; s.moving=false; s.last_checked_dist=d
    end

    local reused_d = s.last_checked_dist or current_distance(actor_id, origin, s.target)

    if type(reused_d) == "number" and reused_d > deps.profile.attack_radius then
      if s.moving then return {action="move", target_id=s.target, reason="chasing"} end
      local ok_move, msg = call(deps.adapter.move_to, actor_id, s.target)
      if not ok_move then return {action="error", target_id=s.target, reason="move_error"} end
      s.moving=true
      return {action="move", target_id=s.target, reason="moving_to_target"}
    end

    local now_t = deps.clock()
    if s.last_attack_time and (now_t - s.last_attack_time) < deps.profile.attack_cooldown then
      return {action="wait", target_id=s.target, reason="on_cooldown"}
    end

    local ok_atk, msg = call(deps.adapter.attack, actor_id, s.target)
    if not ok_atk then return {action="error", target_id=s.target, reason="attack_error"} end
    s.last_attack_time=now_t; s.moving=false
    return {action="attack", target_id=s.target, reason=type(msg)=="string" and msg or "executed"}
  end

  return controller
end

return M
